def longest(a: list[int], b: list[int]) -> list[int]:
    """Return the longer of a and b; on a length tie, return a."""
    return b if len(b) > len(a) else a


def test_longer_second_wins() -> None:
    assert longest([1], [2, 3]) == [2, 3]


def test_longer_first_wins() -> None:
    assert longest([1, 2, 3], [4]) == [1, 2, 3]


def test_tie_returns_first() -> None:
    a = [1, 2]
    b = [3, 4]
    assert longest(a, b) == [1, 2]
    assert longest(a, b) is a


def test_empty_first_and_second() -> None:
    assert longest([], [9]) == [9]
    assert longest([9], []) == [9]


def test_both_empty() -> None:
    assert longest([], []) == []
